<?php use app\services\Ui;use yii\helpers\Html;$personal=Yii::$app->user->identity->role==='teacher'; ?>
<?php if(!$rows): ?><?= Ui::empty('Arizalar yaratilgach shu yerda ko‘rinadi.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Faoliyat</th><?php if(!$personal): ?><th>Xodim</th><?php endif ?><th>Davr</th><th>Holat</th><th class="number">Ball</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><b><?= Ui::h($row['title']) ?></b><small class="truncate"><?= Ui::h($row['indicator']) ?></small></td><?php if(!$personal): ?><td><?= Ui::h($row['employee']) ?></td><?php endif ?><td><?= Ui::h($row['period']) ?></td><td><?= Ui::status($row['status']) ?></td><td class="number score"><?= Ui::money($row['score_cents']) ?><small><?= $row['status']==='approved'?'tasdiqlangan':'dastlabki' ?></small></td><td><?= Html::a('Ko‘rish →',['kpi/view','id'=>$row['id']],['class'=>'text-link']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
